-- Phase 18 fixed-restorative learning content. CAD assets are generated in-app.
-- Restoration geometry is synthetic educational geometry; no patient or licensed library data is included.

insert into public.tool_definitions (id,category,label_en,label_sr,short_description_en,short_description_sr,explanation_en,explanation_sr,status)
values
 ('restorative_workflow','workflow','Restorative workflow','Restorativni postupak','Shared workflow controls for fixed restorative cases.','Zajedničke kontrole postupka za fiksne protetske radove.','Crown, Bridge, Inlay, Onlay and Veneer use one CAD workspace and registered restoration objects.','Crown, Bridge, Inlay, Onlay i Veneer koriste jedan CAD prostor i registrovane objekte nadoknade.','published'),
 ('bridge_units','workflow','Bridge units','Jedinice mosta','Inspect abutments, pontic and connector members in one bridge object.','Pregledajte nosače, međučlan i spojnice unutar jednog objekta mosta.','The training bridge has stable unit identities and one editable connected CAD object.','Probni most ima stabilne identitete jedinica i jedan povezani CAD objekat koji se može menjati.','published'),
 ('pontic_inspection','analysis','Pontic and gingiva inspection','Pregled međučlana i gingive','Inspect the pontic against a synthetic support reference.','Pregledajte međučlan u odnosu na sintetičku referencu potpore.','Use static proximity and Section views for educational inspection; no clinical pontic rule is inferred.','Koristite statičku blizinu i Section prikaz za edukativni pregled; ne izvodi se kliničko pravilo za međučlan.','published')
on conflict (id) do update set category=excluded.category,label_en=excluded.label_en,label_sr=excluded.label_sr,short_description_en=excluded.short_description_en,short_description_sr=excluded.short_description_sr,explanation_en=excluded.explanation_en,explanation_sr=excluded.explanation_sr,status='published';

insert into public.practice_modules (id,slug,title_en,title_sr,summary_en,summary_sr,sort_order,status)
values
 ('b7180000-0000-4000-8000-000000000001','bridge_workflow','Bridge Workflow','Postupak izrade mosta','A connected, multi-unit synthetic bridge case using the shared restorative CAD architecture.','Sintetički slučaj povezanog mosta sa više jedinica u zajedničkoj restorativnoj CAD arhitekturi.',40,'published'),
 ('b7180000-0000-4000-8000-000000000002','inlay_onlay_workflow','Inlay and Onlay Workflow','Postupak izrade Inlay i Onlay nadoknada','Compare two related but distinct partial-coverage restorations using shared CAD tools.','Uporedite dve srodne, ali različite parcijalne nadoknade uz zajedničke CAD alate.',50,'published'),
 ('b7180000-0000-4000-8000-000000000003','veneer_workflow','Veneer Workflow','Postupak izrade fasete','An anterior synthetic veneer case focused on placement and shared surface inspection.','Sintetički slučaj prednje fasete usmeren na pozicioniranje i zajednički pregled površine.',60,'published')
on conflict (slug) do update set title_en=excluded.title_en,title_sr=excluded.title_sr,summary_en=excluded.summary_en,summary_sr=excluded.summary_sr,sort_order=excluded.sort_order,status='published';

insert into public.practice_lessons (id,module_id,slug,difficulty,title_en,title_sr,summary_en,summary_sr,goal_en,goal_sr,estimated_minutes,case_setup,sort_order,status)
select seed.id,module.id,seed.slug,seed.difficulty::public.difficulty_level,seed.title_en,seed.title_sr,seed.summary_en,seed.summary_sr,seed.goal_en,seed.goal_sr,seed.minutes,
 jsonb_build_object('source','restorative-case','restorationType',seed.restoration_type,'objectMappings',jsonb_build_array()),seed.sort_order,'published'
from (values
 ('b7180000-0000-4000-8000-000000000010'::uuid,'bridge_units','bridge_workflow','bridge','beginner',10,'Bridge Units and Margins','Jedinice mosta i margine','Inspect the two abutments, pontic region, connector members and individual preparation margins.','Pregledajte dva nosača, područje međučlana, spojnice i pojedinačne margine preparacija.','Close a separate Margin Line on each abutment preparation.','Zatvorite zasebnu Margin Line na preparaciji svakog nosača.',12),
 ('b7180000-0000-4000-8000-000000000011'::uuid,'bridge_pontic_connectors','bridge_workflow','bridge','intermediate',20,'Pontic, Connectors and Gingiva Relation','Međučlan, spojnice i odnos sa gingivom','Inspect the pontic and adjust connector geometry on the shared bridge object.','Pregledajte međučlan i podesite geometriju spojnica na zajedničkom objektu mosta.','Review the synthetic support region and connector target for this exercise.','Pregledajte sintetičku potpornu regiju i cilj spojnica za ovu vežbu.',12),
 ('b7180000-0000-4000-8000-000000000012'::uuid,'bridge_contacts_thickness','bridge_workflow','bridge','intermediate',30,'Bridge Proximity and Thickness','Blizina i debljina mosta','Inspect static proximal and antagonist relationships and the bridge mesh.','Pregledajte statičke proksimalne odnose, antagonistu i mesh mosta.','Run shared proximity and thickness analyses, then review a Section view.','Pokrenite zajedničke analize blizine i debljine, pa pregledajte Section prikaz.',14),
 ('b7180000-0000-4000-8000-000000000013'::uuid,'bridge_full_case','bridge_workflow','bridge','intermediate',40,'Full Bridge Case · 14–16','Kompletan slučaj mosta · 14–16','Complete the connected bridge exercise with separate abutment margins and shared CAD edits.','Završite vežbu povezanog mosta zasebnim marginama nosača i zajedničkim CAD izmenama.','Review unit identities, close both margins and complete the configured analysis checks.','Pregledajte identitete jedinica, zatvorite obe margine i dovršite podešene analize.',18),
 ('b7180000-0000-4000-8000-000000000020'::uuid,'inlay_margin_insertion','inlay_onlay_workflow','inlay','beginner',10,'Inlay Margin and Insertion Direction','Inlay margina i smer insercije','Inspect the prepared cavity and define a non-destructive Margin Line.','Pregledajte preparisanu kavitaciju i definišite nedestruktivnu Margin Line.','Close the preparation boundary and preview an explicit insertion direction.','Zatvorite granicu preparacije i prikažite izričito izabran smer insercije.',10),
 ('b7180000-0000-4000-8000-000000000021'::uuid,'inlay_contact_thickness','inlay_onlay_workflow','inlay','intermediate',20,'Inlay Contact and Thickness','Inlay kontakt i debljina','Edit the synthetic inlay and inspect neighboring and opposing surfaces.','Izmenite sintetički Inlay i pregledajte susedne i suprotne površine.','Use shared proximity, thickness, Section and Design Check tools.','Koristite zajedničke alate Proximity, Thickness, Section i Design Check.',12),
 ('b7180000-0000-4000-8000-000000000022'::uuid,'onlay_coverage_margin','inlay_onlay_workflow','onlay','beginner',30,'Onlay Coverage and Margin','Onlay pokrivenost i margina','Inspect the broader synthetic occlusal and cusp coverage form.','Pregledajte širi sintetički oblik okluzalne i kvržične pokrivenosti.','Distinguish Onlay coverage from the smaller Inlay form and define its margin.','Razlikujte Onlay pokrivenost od manjeg Inlay oblika i definišite marginu.',10),
 ('b7180000-0000-4000-8000-000000000023'::uuid,'onlay_design_review','inlay_onlay_workflow','onlay','intermediate',40,'Onlay Contact and Thickness Review','Onlay pregled kontakta i debljine','Edit the onlay form and inspect static surface relationships.','Izmenite Onlay oblik i pregledajte statičke odnose površina.','Run shared contact and thickness analyses and inspect the section.','Pokrenite zajedničke analize kontakta i debljine i pregledajte presek.',12),
 ('b7180000-0000-4000-8000-000000000030'::uuid,'veneer_preparation_reference','veneer_workflow','veneer','beginner',10,'Anterior Preparation and Reference','Prednja preparacija i referenca','Inspect the synthetic preparation, adjacent teeth and optional reference model.','Pregledajte sintetičku preparaciju, susedne zube i opcionu referentnu geometriju.','Compare the facial shell with its reference and identify the target tooth 11.','Uporedite fasetnu ljuspicu sa referencom i identifikujte zub 11.',8),
 ('b7180000-0000-4000-8000-000000000031'::uuid,'veneer_position_thickness','veneer_workflow','veneer','intermediate',20,'Veneer Placement and Surface Review','Pozicioniranje fasete i pregled površine','Position the editable veneer and inspect deviation and thickness.','Pozicionirajte fasetu koja se može menjati i pregledajte odstupanje i debljinu.','Use shared transforms, Sculpt, Section and Design Check on the anterior case.','Koristite zajedničke transformacije, Sculpt, Section i Design Check na prednjem slučaju.',12)
) seed(id,slug,module_slug,restoration_type,difficulty,sort_order,title_en,title_sr,summary_en,summary_sr,goal_en,goal_sr,minutes)
join public.practice_modules module on module.slug=seed.module_slug
on conflict (slug) do update set module_id=excluded.module_id,difficulty=excluded.difficulty,title_en=excluded.title_en,title_sr=excluded.title_sr,summary_en=excluded.summary_en,summary_sr=excluded.summary_sr,goal_en=excluded.goal_en,goal_sr=excluded.goal_sr,estimated_minutes=excluded.estimated_minutes,case_setup=excluded.case_setup,sort_order=excluded.sort_order,status='published';

create or replace function pg_temp.seed_phase18_step(
 p_lesson_slug text,p_slug text,p_order integer,p_title_en text,p_title_sr text,p_instruction_en text,p_instruction_sr text,p_theory_en text,p_theory_sr text,p_tools text[],p_targets text[],p_validators jsonb,p_hints jsonb
) returns void language plpgsql as $$
declare lesson_key uuid;step_key uuid;validator_key uuid;validator_value jsonb;hint_value jsonb;tool_value text;validator_type public.validator_type;validator_order integer:=10;
begin
 select id into strict lesson_key from public.practice_lessons where slug=p_lesson_slug;
 insert into public.practice_steps(lesson_id,slug,sort_order,title_en,title_sr,instructions_en,instructions_sr,theory_en,theory_sr,target_object_ids,reference_modes,reference_config,example_config,required)
 values(lesson_key,p_slug,p_order,p_title_en,p_title_sr,p_instruction_en,p_instruction_sr,p_theory_en,p_theory_sr,p_targets,array['off','outline','transparent','full'],null,jsonb_build_object('label_en','Target for this exercise','label_sr','Cilj ove vežbe','mode','outline'),true)
 on conflict(lesson_id,slug) do update set sort_order=excluded.sort_order,title_en=excluded.title_en,title_sr=excluded.title_sr,instructions_en=excluded.instructions_en,instructions_sr=excluded.instructions_sr,theory_en=excluded.theory_en,theory_sr=excluded.theory_sr,target_object_ids=excluded.target_object_ids,reference_modes=excluded.reference_modes,reference_config=excluded.reference_config,example_config=excluded.example_config,required=true returning id into step_key;
 delete from public.practice_hints where step_id=step_key; delete from public.practice_step_tools where step_id=step_key; delete from public.practice_step_validations where step_id=step_key;
 foreach tool_value in array p_tools loop insert into public.practice_step_tools(step_id,tool_id) values(step_key,tool_value) on conflict do nothing; end loop;
 for validator_value in select value from jsonb_array_elements(coalesce(p_validators,'[]'::jsonb)) loop
  validator_type:=case when validator_value->>'type' in ('analysis_target','restorative_setup') then 'custom'::public.validator_type else (validator_value->>'type')::public.validator_type end;
  insert into public.validation_configs(slug,validator_type,config,status) values('restorative_'||p_lesson_slug||'_'||p_slug||'_'||(validator_value->>'type')||'_'||coalesce(validator_value->>'kind',validator_value->>'check','check')||'_'||substr(md5(validator_value::text),1,10),validator_type,validator_value,'published')
  on conflict(slug) do update set validator_type=excluded.validator_type,config=excluded.config,status='published' returning id into validator_key;
  insert into public.practice_step_validations(step_id,validation_config_id,sort_order) values(step_key,validator_key,validator_order) on conflict(step_id,validation_config_id) do update set sort_order=excluded.sort_order;
  validator_order:=validator_order+10;
 end loop;
 for hint_value in select value from jsonb_array_elements(coalesce(p_hints,'[]'::jsonb)) loop
  insert into public.practice_hints(step_id,slug,sort_order,title_en,title_sr,body_en,body_sr) values(step_key,hint_value->>'slug',(hint_value->>'order')::integer,hint_value->>'title_en',hint_value->>'title_sr',hint_value->>'body_en',hint_value->>'body_sr');
 end loop;
end $$;

select pg_temp.seed_phase18_step('bridge_units','bridge_setup',10,'Inspect the bridge units and margins','Pregledajte jedinice mosta i margine',
 'Select each preparation in turn. Draw and close one Margin Line on the 14 abutment and a separate Margin Line on the 16 abutment, then run Design Check.',
 'Redom izaberite svaku preparaciju. Nacrtajte i zatvorite jednu Margin Line na nosaču 14, a zasebnu Margin Line na nosaču 16, pa pokrenite Design Check.',
 'The bridge is one editable CAD object with stable abutment, pontic and connector member identities. Each preparation margin remains attached to its own object in local coordinates.',
 'Most je jedan CAD objekat koji se može menjati, sa stabilnim identitetima nosača, međučlana i spojnica. Margina svake preparacije ostaje povezana sa sopstvenim objektom u lokalnim koordinatama.',
 array['select','camera','scene','analysis'],array['restorative-bridge-preparation-14','restorative-bridge-preparation-16','restorative-bridge-bridge'],
 '[{"type":"margin_complete","objectId":"restorative-bridge-preparation-14"},{"type":"margin_complete","objectId":"restorative-bridge-preparation-16"},{"type":"restorative_setup","check":"bridge_design","restorationType":"bridge"}]'::jsonb,
 '[{"slug":"separate-surfaces","order":10,"title_en":"Keep the margins attached","title_sr":"Ostavite margine povezane","body_en":"Choose each abutment preparation from the workflow controls before drawing. Margin points are accepted only on the selected preparation.","body_sr":"Pre crtanja izaberite svaki nosač u kontrolama postupka. Tačke margine prihvataju se samo na izabranoj preparaciji."},{"slug":"closed-curves","order":20,"title_en":"Close both curves","title_sr":"Zatvorite obe krive","body_en":"The two Margin Lines have separate object IDs and undo history. Both must be closed for this setup check.","body_sr":"Dve Margin Line krive imaju zasebne ID-jeve objekata i istoriju poništavanja. Obe moraju biti zatvorene za ovu proveru."}]');

select pg_temp.seed_phase18_step('bridge_pontic_connectors','pontic_connector_review',10,'Inspect the pontic, connectors and support region','Pregledajte međučlan, spojnice i potpornu regiju',
 'Inspect the central pontic against the synthetic gingiva region. Adjust the connector diameter slider, then use Undo and Redo to review the geometry history.',
