 '[{"type":"analysis_target","kind":"contact","objectIds":["restorative-bridge-bridge","restorative-bridge-adjacent-13"]},{"type":"analysis_target","kind":"contact","objectIds":["restorative-bridge-bridge","restorative-bridge-antagonist-44"]},{"type":"analysis_target","kind":"thickness","objectIds":["restorative-bridge-bridge"]}]'::jsonb,
 '[{"slug":"static-only","order":10,"title_en":"Use explicit object pairs","title_sr":"Izaberite parove objekata","body_en":"Choose the two named objects in the analysis controls. Run each comparison separately and read the measured range.","body_sr":"Izaberite dva navedena objekta u kontrolama analize. Pokrenite svako poređenje zasebno i pregledajte izmereni opseg."},{"slug":"section-view","order":20,"title_en":"Inspect a section","title_sr":"Pregledajte presek","body_en":"Section clips only the viewport. It does not alter bridge mesh data.","body_sr":"Section odseca samo prikaz u viewport-u. Ne menja podatke mesh-a mosta."}]');

