insert into public.scenarios(domain_id,slug,difficulty,title_en,title_sr,description_en,description_sr,patient_code,patient_age,indication_en,indication_sr,tooth_numbers,requirements_en,requirements_sr,additional_metadata,random_eligible,status,published_at)
select domain.id,seed.slug,seed.difficulty::public.difficulty_level,seed.title_en,seed.title_sr,seed.description_en,seed.description_sr,seed.patient_code,null,seed.indication_en,seed.indication_sr,seed.tooth_numbers,seed.requirements_en,seed.requirements_sr,seed.metadata::jsonb,true,'published',now()
from (values
 ('bridge','synthetic_bridge_14_16','intermediate','Bridge 14–16','Most 14–16','Connected three-unit synthetic bridge with two editable abutment margins, central pontic and adjustable connector members.','Povezan sintetički most od tri jedinice sa marginama dva nosača, centralnim međučlanom i podesivim spojnicama.','PT-TR-181','Three-unit bridge training case','Vežba za tročlani most',array[14,15,16]::smallint[],array['Inspect both abutments','Define two separate margins','Review pontic support and connectors','Check static proximal and antagonist relationships'],array['Pregledajte oba nosača','Definišite dve zasebne margine','Pregledajte potporu međučlana i spojnice','Proverite statičke proksimalne i antagonističke odnose'],'{"caseInitializer":"restorative","restorationType":"bridge","geometryProvenance":"internal-synthetic-educational","noPatientData":true,"materialPreset":"synthetic_training","material":{"en":"Synthetic educational preset","sr":"Sintetički edukativni materijal"},"supplied":{"en":["Two synthetic abutment preparations","Adjacent teeth and antagonist","Pontic support region","Connected bridge restoration"],"sr":["Dve sintetičke preparacije nosača","Susedni zubi i antagonist","Potporna regija međučlana","Povezana mostna nadoknada"]},"notes":{"en":"All geometry is generated in Prostheia for education. Static proximity does not simulate jaw motion or establish clinical suitability.","sr":"Sva geometrija je generisana u Prostheia za edukaciju. Statička blizina ne simulira kretanje vilice niti utvrđuje kliničku podobnost."}}'),
 ('inlay_onlay','synthetic_inlay_36','beginner','Inlay 36','Inlay 36','Synthetic cavity preparation with a distinct partial-coverage Inlay starting form and antagonist.','Sintetička preparacija kaviteta sa zasebnim početnim oblikom parcijalne Inlay nadoknade i antagonistom.','PT-TR-182','Inlay training case','Vežba za Inlay',array[36]::smallint[],array['Inspect the prepared cavity','Define its Margin Line','Review insertion direction','Check proximal and antagonist proximity and thickness'],array['Pregledajte preparisani kavitet','Definišite Margin Line','Pregledajte smer insercije','Proverite proksimalnu i antagonističku blizinu i debljinu'],'{"caseInitializer":"restorative","restorationType":"inlay","geometryProvenance":"internal-synthetic-educational","noPatientData":true,"materialPreset":"synthetic_training","material":{"en":"Synthetic educational preset","sr":"Sintetički edukativni materijal"},"supplied":{"en":["Synthetic preparation 36","Synthetic adjacent teeth","Synthetic antagonist","Editable Inlay and example reference"],"sr":["Sintetička preparacija 36","Sintetički susedni zubi","Sintetički antagonist","Inlay koji se može menjati i primer reference"]},"notes":{"en":"The starter form is not an automatic cavity fit or clinical design recommendation.","sr":"Početni oblik nije automatsko naleganje u kavitet niti klinička preporuka dizajna."}}'),
 ('inlay_onlay','synthetic_onlay_46','intermediate','Onlay 46','Onlay 46','Synthetic broader occlusal and cusp coverage form with preparation, adjacent surfaces and antagonist.','Sintetički širi oblik okluzalne i kvržične pokrivenosti sa preparacijom, susednim površinama i antagonistom.','PT-TR-183','Onlay training case','Vežba za Onlay',array[46]::smallint[],array['Inspect the broader cusp coverage','Define the preparation margin','Edit the Onlay with shared tools','Review static proximity and thickness'],array['Pregledajte širu pokrivenost kvržica','Definišite marginu preparacije','Izmenite Onlay zajedničkim alatima','Pregledajte statičku blizinu i debljinu'],'{"caseInitializer":"restorative","restorationType":"onlay","geometryProvenance":"internal-synthetic-educational","noPatientData":true,"materialPreset":"synthetic_training","material":{"en":"Synthetic educational preset","sr":"Sintetički edukativni materijal"},"supplied":{"en":["Synthetic preparation 46","Synthetic adjacent teeth","Synthetic antagonist","Editable broader-coverage Onlay"],"sr":["Sintetička preparacija 46","Sintetički susedni zubi","Sintetički antagonist","Onlay sa širom pokrivenošću koji se može menjati"]},"notes":{"en":"Coverage geometry is an educational visual distinction and does not imply automatic fit.","sr":"Geometrija pokrivenosti je edukativna vizuelna razlika i ne podrazumeva automatsko naleganje."}}'),
 ('veneer','synthetic_veneer_11','beginner','Anterior Veneer 11','Prednja faseta 11','Synthetic anterior veneer case with preparation, adjacent teeth, antagonist and reference form.','Sintetički slučaj prednje fasete sa preparacijom, susednim zubima, antagonistom i referentnim oblikom.','PT-TR-184','Anterior Veneer training case','Vežba za prednju fasetu',array[11]::smallint[],array['Inspect the anterior preparation and reference','Position the veneer shell','Review deviation, thickness and section'],array['Pregledajte prednju preparaciju i referencu','Pozicionirajte fasetnu ljuspicu','Pregledajte odstupanje, debljinu i presek'],'{"caseInitializer":"restorative","restorationType":"veneer","geometryProvenance":"internal-synthetic-educational","noPatientData":true,"materialPreset":"synthetic_training","material":{"en":"Synthetic educational preset","sr":"Sintetički edukativni materijal"},"supplied":{"en":["Synthetic preparation 11","Synthetic adjacent teeth","Synthetic antagonist","Editable anterior shell and reference"],"sr":["Sintetička preparacija 11","Sintetički susedni zubi","Sintetički antagonist","Prednja ljuska i referenca koje se mogu menjati"]},"notes":{"en":"This visual case is for education only and does not provide a clinical veneer preparation or thickness prescription.","sr":"Ovaj vizuelni slučaj služi samo edukaciji i ne daje klinički postupak preparacije fasete niti propis debljine."}}')
) seed(domain_slug,slug,difficulty,title_en,title_sr,description_en,description_sr,patient_code,indication_en,indication_sr,tooth_numbers,requirements_en,requirements_sr,metadata)
join public.content_domains domain on domain.slug=seed.domain_slug
where not exists(select 1 from public.scenarios scenario where scenario.slug=seed.slug);

update public.practice_modules set status='published' where slug in ('bridge_workflow','inlay_onlay_workflow','veneer_workflow');
